import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Why xclang?","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Why xclang? | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/guide/why-xclang"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/guide/why-xclang"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/guide/why-xclang"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/guide/why-xclang"}]]},"headers":[],"relativePath":"xclang/guide/why-xclang.md","filePath":"en/xclang/guide/why-xclang.md","lastUpdated":1791579933000}'),n={name:"xclang/guide/why-xclang.md"};function i(s,e,d,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="why-xclang" tabindex="-1">Why xclang? <a class="header-anchor" href="#why-xclang" aria-label="Permalink to &quot;Why xclang?&quot;">​</a></h1><p>A C++ build is <em>hermetic</em> when its result depends only on its declared inputs. The same sources and toolchain give the same program, on any machine and in any directory. Most C++ toolchains are not built for that. They take headers and libraries from the machine, and link runtimes that the target machine has to provide. They write the paths of the build into the output. xclang aims at the current best practice for hermetic, modern C++ builds.</p><h2 id="at-a-glance" tabindex="-1">At a Glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a Glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>what it means for you</th><th>details</th></tr></thead><tbody><tr><td><a href="#reproducible">Reproducible</a></td><td>one pinned toolchain; Bazel builds that are the same bytes in any checkout</td><td><a href="./../design/bazel-module">the Bazel module</a></td></tr><tr><td><a href="#portable-programs">Portable programs</a></td><td>a program runs on any machine of its target, as one file</td><td><a href="./../design/hermeticity">hermeticity</a></td></tr><tr><td><a href="#cross-compiling-is-a-flag">Cross-compiling is a flag</a></td><td>one compiler version for eight targets, no sysroots to install</td><td><a href="./cross-compiling">cross-compiling</a></td></tr><tr><td><a href="#correct-build-caches">Correct build caches</a></td><td>a cache never serves objects of another compiler</td><td><a href="./../design/bazel-module#every-toolchain-file-is-an-input">the Bazel module</a></td></tr><tr><td><a href="#c-20-modules">C++20 modules</a></td><td><code>import std</code> in CMake 3.28 or later without experimental switches, and in Bazel</td><td><a href="./../features/modules">C++20 modules</a></td></tr><tr><td><a href="#fast">Fast</a></td><td>clang and lld built with PGO and ThinLTO, on every host</td><td><a href="./../design/pgo">PGO</a></td></tr><tr><td><a href="#correctness-tools">Correctness tools</a></td><td>sanitizers that report real bugs, debug symbols for every target</td><td><a href="./../features/sanitizers">sanitizers</a>, <a href="./../features/debugging">debugging</a></td></tr><tr><td><a href="#supply-chain">Supply chain</a></td><td>every archive pinned by sha256, LLVM&#39;s source with documented patches</td><td><a href="./../reference/releases">releases</a></td></tr><tr><td><a href="#one-toolchain-for-every-build">One toolchain for every build</a></td><td>the same compiler for CMake, Bazel, Meson, Make and cargo</td><td><a href="./install">installation</a></td></tr></tbody></table><p>How each claim is tested is in <a href="./../dev/testing">testing</a>.</p><h2 id="reproducible" tabindex="-1">Reproducible <a class="header-anchor" href="#reproducible" aria-label="Permalink to &quot;Reproducible&quot;">​</a></h2><p>A toolchain is a release, and a release is never replaced: a rebuild is the next revision. The Bazel module pins each archive by its sha256, and the CMake download checks it. So two developers and a CI runner build with the same compiler. In Bazel builds, no command line or debug information holds an absolute path, but for the macOS SDK. A program built in a second checkout is the same bytes.</p><h2 id="portable-programs" tabindex="-1">Portable Programs <a class="header-anchor" href="#portable-programs" aria-label="Permalink to &quot;Portable Programs&quot;">​</a></h2><p>A program depends at run time only on what every installation of its OS has. That is glibc 2.17 or later, Windows 10 or later, or macOS 13 or later. libc++ and the other runtimes are linked into it. That is what Rust does by default. Chromium arranges it for itself, with a Debian sysroot and its own libc++ built into the browser. Build scripts written for GCC (<code>-latomic</code>, <code>-lgcc_s</code>, <code>-lstdc++</code>) link unchanged.</p><h2 id="cross-compiling-is-a-flag" tabindex="-1">Cross-Compiling Is a Flag <a class="header-anchor" href="#cross-compiling-is-a-flag" aria-label="Permalink to &quot;Cross-Compiling Is a Flag&quot;">​</a></h2><p>Cross toolchains have traditionally been one per target: a distribution package, a MinGW GCC or a Docker image. Each has its own compiler version and sysroot. clang already compiles for every LLVM target; what it lacks is the libraries of each target. xclang ships them next to the compiler, so <code>clang++ --target=aarch64-w64-mingw32</code> is the whole difference. A bug fixed or a warning added in one compiler version applies to all targets at once.</p><h2 id="correct-build-caches" tabindex="-1">Correct Build Caches <a class="header-anchor" href="#correct-build-caches" aria-label="Permalink to &quot;Correct Build Caches&quot;">​</a></h2><p>A cache is only as correct as its key. With a compiler found on the machine, a new compiler version rebuilds nothing, and the cache serves objects of the old one. In Bazel, every toolchain file that an action reads is a declared input. A new release rebuilds what it should, and a disk or remote cache can serve any machine. Module files are inputs of their importers too, which is where ccache goes wrong (<a href="./../features/modules#build-caches-and-modules">build caches and modules</a>).</p><h2 id="c-20-modules" tabindex="-1">C++20 Modules <a class="header-anchor" href="#c-20-modules" aria-label="Permalink to &quot;C++20 Modules&quot;">​</a></h2><p>A module file is only usable by importers compiled with the same language options. So a prebuilt <code>std</code> module cannot be shipped. xclang builds the <code>std</code> and <code>std.compat</code> modules of libc++ for each build, with its options, as a library to link. It is <code>xclang::std</code> in CMake, and <code>@xclang//bazel:std</code> in Bazel. CMake needs no experimental switch.</p><h2 id="fast" tabindex="-1">Fast <a class="header-anchor" href="#fast" aria-label="Permalink to &quot;Fast&quot;">​</a></h2><p>A compiler runs thousands of times per build, so its own speed is a large part of the build time. clang and lld are built with PGO and ThinLTO on every host. The profile comes from compiling real code, the way builds and editors do.</p><p>On C++, 23.1.2.6 compiles as fast as LLVM&#39;s own builds on Linux and macOS, and faster than LLVM&#39;s build on Windows. libclang ships as ThinLTO bitcode, and the <a href="./../features/thinlto-cache">ThinLTO cache</a> makes the relinks of tools built on it take seconds.</p><h2 id="correctness-tools" tabindex="-1">Correctness Tools <a class="header-anchor" href="#correctness-tools" aria-label="Permalink to &quot;Correctness Tools&quot;">​</a></h2><p>ASan, TSan, LSan, UBSan and libFuzzer work for Linux and macOS targets; UBSan for the MSVC targets, and ASan and libFuzzer for x64 ones. An ASan program against an uninstrumented libc++ reports container overflows that are not there. So xclang ships an ASan build of libc++, which ASan programs link. Debug information holds wherever the build ran, and the toolchain makes GSYM files for every target, the same file on every run, and dSYMs for macOS ones.</p><h2 id="supply-chain" tabindex="-1">Supply Chain <a class="header-anchor" href="#supply-chain" aria-label="Permalink to &quot;Supply Chain&quot;">​</a></h2><p>Every archive is listed in the <code>SHA256SUMS</code> of its release, and the Bazel module pins each by sha256. LLVM&#39;s source is the release tarball, pinned by sha256, with the patches in the repository applied. Every patch has a README saying what it changes and where it stands upstream. Each host&#39;s archives are made twice, on two machines, and must be the same bytes. Every archive carries the licenses of its components, with an SPDX document (<a href="./../reference/layout#licenses">layout</a>).</p><p>Vendor SDKs, such as Apple&#39;s and Microsoft&#39;s, are never in an archive: the user fetches them from the vendor, pinned by version and sha256 (<a href="./../design/vendor-sdks">vendor SDKs</a>). A toolchain runs on every developer machine and writes every shipped binary. Knowing which source built it, and that the bytes downloaded are the bytes published, is the minimum.</p><h2 id="one-toolchain-for-every-build" tabindex="-1">One Toolchain for Every Build <a class="header-anchor" href="#one-toolchain-for-every-build" aria-label="Permalink to &quot;One Toolchain for Every Build&quot;">​</a></h2><p>A project usually has more than one build: the main one, a script, a Rust crate with C code, a test harness. With different compilers, their outputs differ in subtle ways, such as another libc++ or another glibc floor. The same toolchain directory is the compiler of plain clang, CMake, Bazel, Meson, Make, and cargo&#39;s C code and links. It comes from pixi, an archive, FetchContent or the Bazel registry.</p><h2 id="not-yet-supported" tabindex="-1">Not Yet Supported <a class="header-anchor" href="#not-yet-supported" aria-label="Permalink to &quot;Not Yet Supported&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>status</th></tr></thead><tbody><tr><td><a href="./../design/roadmap#targets">More Linux architectures, WebAssembly, Android, BSDs, bare metal</a></td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a href="./../design/roadmap#msan">MemorySanitizer, through libc++ built on demand</a></td><td><span class="status-badge warn">Unreleased</span></td></tr><tr><td><a href="./../design/roadmap#mingw-sanitizers">Sanitizers for MinGW targets</a></td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a href="./../design/roadmap#cmake-relative-paths">Relative debug paths in CMake builds</a></td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a href="./../design/roadmap#immutable-releases">Immutable releases</a></td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a href="./../design/roadmap#slsa">SLSA provenance</a></td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a href="./../design/roadmap#bolt">BOLT</a></td><td><span class="status-badge note">In research</span></td></tr><tr><td><a href="./../design/roadmap#pgo-training">A wider PGO training</a></td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a href="./../design/roadmap#cargo-helper"><code>xclang cargo</code></a>, cargo set up for xclang&#39;s targets</td><td><span class="status-badge warn">Unreleased</span></td></tr></tbody></table><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li><strong>One libc++ per shared object.</strong> A standard exception from one shared library is caught in another only by <code>catch (...)</code> on Linux and macOS (<a href="./../design/hermeticity#one-libc-per-shared-object">hermeticity</a>).</li><li><strong>No Bazel sandbox on Windows</strong> by default: an action can read undeclared files there. The Linux and macOS builds of the same targets enforce the declarations.</li><li><strong>Header units</strong> are built by neither CMake nor Bazel, and Bazel&#39;s module support is experimental.</li><li><strong>glibc 2.17 has no <code>-static-pie</code></strong> (<a href="./../reference/compatibility#known-limitations">compatibility</a>).</li></ul>',29)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
